<?php require_once __DIR__.'/includes/bootstrap.php'; if(is_logged_in()) redirect('/dashboard.php');$errors=[];$email='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$s=$pdo->prepare('SELECT id,password_hash FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];flash('success','Welcome back!');redirect('/dashboard.php');}$errors[]='Email or password is incorrect.';}$page_title='Log in';require __DIR__.'/includes/header.php'; ?>
<div class="auth-wrap"><section class="panel form-panel"><h1>Welcome back</h1><p class="muted">Log in to continue to your dashboard.</p><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><form method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Email address<input type="email" name="email" required value="<?= e($email) ?>" autocomplete="email"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><div class="form-row"><a href="forgot_password.php">Forgot password?</a></div><button class="button primary" type="submit">Log in</button></form><p class="form-foot">New to EventPro? <a href="register.php">Create an account</a></p></section></div><?php require __DIR__.'/includes/footer.php'; ?>